INSERT INTO public.skill_registry (slug, name, description, department, category, tags, quality_score, author, is_public, is_verified, source_repo, source_url, source_license)
SELECT v.slug, v.name, v.description, v.department, v.category, v.tags, v.quality_score, 'Nexus', true, true, 'obra/superpowers', 'https://github.com/obra/superpowers', 'MIT'
FROM (VALUES
('nexus-brainstorming-socratico','Brainstorming Socrático de Requisitos','Conduz uma rodada de perguntas socráticas antes de qualquer implementação, expõe premissas ocultas, mapeia alternativas descartadas e só encerra quando o escopo e os critérios de aceite estiverem inequívocos.','ti','prompts',ARRAY['ti','brainstorming','requisitos','descoberta','escopo','premissas','design'],93),
('nexus-plano-de-implementacao','Redação de Planos de Implementação','Transforma um pedido vago em plano executável com tarefas atômicas, ordem de dependência, critérios de verificação por etapa e um plano de rollback explícito antes de escrever a primeira linha de código.','ti','workflows',ARRAY['ti','plano','planejamento','tarefas','rollback','entrega','deploy'],94),
('nexus-execucao-de-planos','Execução Disciplinada de Planos','Executa um plano tarefa a tarefa, sem antecipar etapas nem agrupar mudanças, registrando evidência de verificação a cada passo e interrompendo a execução quando a realidade diverge do plano.','ti','workflows',ARRAY['ti','execucao','plano','disciplina','evidencia','pipeline','deploy'],92),
('nexus-tdd-red-green-refactor','TDD Red-Green-Refactor','Impõe o ciclo teste-primeiro: escreve o teste que falha, comprova a falha pelo motivo certo, implementa o mínimo para passar e só então refatora, proibindo código de produção sem teste que o justifique.','ti','workflows',ARRAY['ti','tdd','teste','testes','refactor','qualidade','ci','pipeline'],96),
('nexus-depuracao-sistematica','Depuração Sistemática de Causa Raiz','Aplica o método de quatro fases — reproduzir, isolar, formular hipótese falseável e corrigir a causa raiz — vetando correções sintomáticas e exigindo um teste que reproduza o defeito antes do conserto.','ti','workflows',ARRAY['ti','debug','depuracao','incidente','troubleshooting','causa','raiz','logs'],95),
('nexus-verificacao-antes-de-concluir','Verificação Antes de Concluir','Bloqueia a declaração de "pronto" enquanto não houver evidência executada: build, testes, lint e checagem manual do caminho feliz, com a saída real anexada em vez de afirmações não comprovadas.','ti','workflows',ARRAY['ti','verificacao','qualidade','checklist','build','ci','deploy','monitoramento'],94),
('nexus-solicitar-code-review','Solicitação de Code Review Eficaz','Prepara o pedido de revisão com contexto, diff enxuto, riscos conhecidos e as perguntas específicas que o revisor deve responder, reduzindo idas e vindas e revisões superficiais.','ti','prompts',ARRAY['ti','code','review','revisao','pull','request','qualidade','colaboracao'],89),
('nexus-receber-code-review','Recepção Crítica de Code Review','Trata cada apontamento de revisão como hipótese a ser avaliada: classifica em aceitar, contestar com evidência ou adiar com registro, e proíbe mudanças automáticas sem entender o motivo do apontamento.','ti','prompts',ARRAY['ti','code','review','feedback','revisao','qualidade','colaboracao'],88),
('nexus-agentes-paralelos','Despacho de Agentes em Paralelo','Decompõe um trabalho grande em frentes independentes, despacha sub-agentes com contrato de entrada e saída explícito e consolida os resultados, evitando conflito de escrita no mesmo arquivo ou recurso.','ti','workflows',ARRAY['ti','agentes','paralelismo','orquestracao','subagente','infra','pipeline'],91),
('nexus-desenvolvimento-por-subagentes','Desenvolvimento Orientado a Sub-agentes','Estrutura a entrega em ciclos delegados: um sub-agente implementa, outro revisa com olhar limpo e um terceiro verifica, mantendo o contexto principal enxuto e as decisões auditáveis.','ti','workflows',ARRAY['ti','subagente','delegacao','ciclo','revisao','arquitetura','devops'],90),
('nexus-git-worktrees','Isolamento de Trabalho com Git Worktrees','Cria uma worktree dedicada por frente de trabalho para isolar experimentos, permitir execução paralela de testes e descartar tentativas fracassadas sem poluir a branch principal.','ti','tools',ARRAY['ti','git','worktree','branch','isolamento','devops','pipeline'],87),
('nexus-encerramento-de-branch','Encerramento de Branch de Desenvolvimento','Fecha uma frente de trabalho com ritual completo: rebase limpo, suíte verde, remoção de código morto e artefatos temporários, mensagem de merge descritiva e limpeza das worktrees e branches remotas.','ti','workflows',ARRAY['ti','git','branch','merge','deploy','ci','cd','limpeza'],88),
('nexus-escrita-de-skills','Escrita de Skills para Agentes','Define o padrão de autoria de skills: gatilho de ativação explícito, instruções imperativas e testáveis, exemplos negativos do que não fazer e critério objetivo de sucesso para o agente.','ti','knowledge',ARRAY['ti','skill','skills','autoria','prompt','agente','documentacao'],92),
('nexus-uso-de-skills','Seleção e Uso de Skills em Runtime','Orienta o agente a inventariar as skills disponíveis, escolher a mais específica para a tarefa, seguir o processo por inteiro e declarar qual skill foi aplicada em cada etapa da execução.','ti','knowledge',ARRAY['ti','skill','skills','runtime','selecao','agente','orquestracao'],89)
) AS v(slug,name,description,department,category,tags,quality_score)
ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, department=EXCLUDED.department, category=EXCLUDED.category, tags=EXCLUDED.tags, quality_score=EXCLUDED.quality_score, source_repo=EXCLUDED.source_repo, source_url=EXCLUDED.source_url, source_license=EXCLUDED.source_license, updated_at=now();